INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('삿포로 눈축제', 'さっぽろ雪まつり', '北海道', '札幌市中央区', DATE '2027-02-04', DATE '2027-02-11', 2027, 43.059800, 141.349700, '오도리 공원 약 1.5km에 거대한 눈 조각과 얼음 조각이 늘어서는 홋카이도 대표 겨울 축제. 밤에는 조각에 조명과 프로젝션 매핑을 비추고, 스스키노 회장에는 얼음 조각이 모인다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('오타루 유키아카리노미치', '小樽雪あかりの路', '北海道', '小樽市', DATE '2027-02-06', DATE '2027-02-13', 2027, 43.198700, 141.001000, '오타루 운하와 옛 데미야선 철길을 수만 개의 촛불로 밝히는 겨울 행사. 운하 수면에 유리 부표 캔들이 떠 있고, 점등은 17시부터 21시까지다.', NULL, 'http://yukiakarinomichi.org/', NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('아사히카와 겨울축제', '旭川冬まつり', '北海道', '旭川市', DATE '2027-02-06', DATE '2027-02-11', 2027, 43.776700, 142.358000, '이시카리강 아사히바시 강변에 기네스 기록에 오른 적 있는 거대 눈 조각과 미끄럼틀이 세워지는 축제. 헤이와도리 거리에서는 얼음 조각 세계대회가 함께 열린다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('나마하게 세도 마쓰리', 'なまはげ柴灯まつり', '秋田県', '男鹿市', DATE '2027-02-12', DATE '2027-02-14', 2027, 39.953000, 139.744000, '신잔 신사의 신사 ''세도사이''와 섣달그믐 민속 행사 ''나마하게''를 합친 오가반도의 겨울 축제. 횃불을 든 나마하게가 눈 덮인 산에서 내려오는 ''하산''이 절정이다.', NULL, 'https://oganavi.com/sedo/', DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('요코테 가마쿠라', '横手の雪まつり かまくら', '秋田県', '横手市', DATE '2027-02-15', DATE '2027-02-16', 2027, 39.311200, 140.553000, '450년 역사의 눈 축제로, 시내 곳곳에 눈집(가마쿠라)을 만들고 안에 수신을 모신다. 아이들이 가마쿠라 안에서 떡과 감주를 대접하며 ''들어와서 수신께 참배하세요''라고 부른다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('YOSAKOI 소란 마쓰리', 'YOSAKOIソーラン祭り', '北海道', '札幌市中央区', DATE '2027-06-09', DATE '2027-06-13', 2027, 43.060500, 141.352000, '나루코를 손에 들고 소란부시 가락을 넣은 곡에 맞춰 팀별로 춤추는 삿포로 초여름 축제. 약 250개 팀이 오도리 공원을 중심으로 시내 곳곳에서 춤을 겨룬다.', NULL, NULL, NULL, NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('홋카이도 신궁 예제 (삿포로 마쓰리)', '北海道神宮例祭（札幌まつり）', '北海道', '札幌市中央区', DATE '2027-06-14', DATE '2027-06-16', 2027, 43.054200, 141.308000, '삿포로의 수호신을 모시는 홋카이도 신궁의 가장 큰 제례. 16일 신위를 실은 가마와 수레 행렬이 시내를 돌고, 나카지마 공원에는 노점이 늘어선다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('아오모리 네부타 마쓰리', '青森ねぶた祭', '青森県', '青森市', DATE '2027-08-02', DATE '2027-08-07', 2027, 40.829600, 140.735000, '무사와 신화를 그린 거대한 등롱 수레(네부타)가 밤거리를 누비는 도호쿠 대표 여름 축제. 하네토 의상을 입으면 누구나 행렬에 섞여 ''랏세라'' 구호와 함께 뛸 수 있다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('아키타 간토 마쓰리', '秋田竿燈まつり', '秋田県', '秋田市', DATE '2027-08-03', DATE '2027-08-06', 2027, 39.719200, 140.121000, '등롱 수십 개를 매단 긴 장대(간토)를 손바닥·이마·허리에 올려 균형을 잡는 아키타의 여름 축제. 밤의 간토 대로에 280여 개의 간토가 벼 이삭처럼 늘어선다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('야마가타 하나가사 마쓰리', '山形花笠まつり', '山形県', '山形市', DATE '2027-08-05', DATE '2027-08-07', 2027, 38.252000, 140.335000, '홍화 장식을 단 삿갓(하나가사)을 들고 ''얏쇼 마카쇼'' 구호와 함께 춤추며 행진하는 축제. 1만 명 넘는 무용수가 도카마치·혼초 거리를 메운다.', NULL, NULL, DATE '2026-11-14', NULL);
INSERT INTO festivals (name, name_ja, prefecture, city, start_date, end_date, festival_year, lat, lng, description, tips, official_url, verified_at, image_url) VALUES ('센다이 다나바타 마쓰리', '仙台七夕まつり', '宮城県', '仙台市青葉区', DATE '2027-08-06', DATE '2027-08-08', 2027, 38.262000, 140.874000, '센다이역 앞과 중심 상점가 아케이드를 화려한 대나무 장식이 뒤덮는 칠석 축제. 전날 밤 8/5에는 전야제 불꽃놀이가 있다.', NULL, NULL, DATE '2026-11-14', NULL);